    68      const [lastPaymentMethod = '-1', lastPaymentMethodResult] = useOnyx(ONYXKEYS.NVP_LAST_PAYMENT_METHOD, {selector: (paymentMethod) => paymentMethod?.[policyID]});
    69      const isLoadingLastPaymentMethod = isLoadingOnyxValue(lastPaymentMethodResult);
    70      const [policy] = useOnyx(`${ONYXKEYS.COLLECTION.POLICY}${policyID}`);
    71      const isInvoiceReport = (!isEmptyObject(iouReport) && ReportUtils.isInvoiceReport(iouReport)) || false;
    72      const shouldShowPaywithExpensifyOption = !shouldHidePaymentOptions;
    73      const shouldShowPayElsewhereOption = !shouldHidePaymentOptions && !isInvoiceReport;
    74      const paymentButtonOptions = useMemo(() => {
    75          const buttonOptions = [];
    76          const isExpenseReport = ReportUtils.isExpenseReport(iouReport);
    77          const paymentMethods = {
    78              [CONST.IOU.PAYMENT_TYPE.EXPENSIFY]: {
    79                  text: translate('iou.settleExpensify', {formattedAmount}),
    80                  icon: Expensicons.Wallet,
    81                  value: CONST.IOU.PAYMENT_TYPE.EXPENSIFY,
    82              },
    83              [CONST.IOU.PAYMENT_TYPE.VBBA]: {
    84                  text: translate('iou.settleExpensify', {formattedAmount}),
    85                  icon: Expensicons.Wallet,
    86                  value: CONST.IOU.PAYMENT_TYPE.VBBA,
    87              },
    88              [CONST.IOU.PAYMENT_TYPE.ELSEWHERE]: {
    89                  text: translate('iou.payElsewhere', {formattedAmount}),
    90                  icon: Expensicons.Cash,
    91                  value: CONST.IOU.PAYMENT_TYPE.ELSEWHERE,
    92              },
    93          };
    94          const approveButtonOption = {
    95              text: translate('iou.approve'),
    96              icon: Expensicons.ThumbsUp,
    97              value: CONST.IOU.REPORT_ACTION_TYPE.APPROVE,
    98              disabled: !!shouldDisableApproveButton,
    99          };
   100          const canUseWallet = !isExpenseReport && !isInvoiceReport && currency === CONST.CURRENCY.USD;
   101
   102          // Only show the Approve button if the user cannot pay the expense
   103          if (shouldHidePaymentOptions && shouldShowApproveButton) {
   104              return [approveButtonOption];
   105          }
   106
   107          if (onlyShowPayElsewhere) {
   108              return [paymentMethods[CONST.IOU.PAYMENT_TYPE.ELSEWHERE]];
   109          }
   110
   111          // To achieve the one tap pay experience we need to choose the correct payment type as default.
   112          if (canUseWallet) {
   113              buttonOptions.push(paymentMethods[CONST.IOU.PAYMENT_TYPE.EXPENSIFY]);
   114          }
   115          if (isExpenseReport && shouldShowPaywithExpensifyOption) {
   116              buttonOptions.push(paymentMethods[CONST.IOU.PAYMENT_TYPE.VBBA]);
   117          }
   118          if (shouldShowPayElsewhereOption) {
   119              buttonOptions.push(paymentMethods[CONST.IOU.PAYMENT_TYPE.ELSEWHERE]);
   120          }
   121
   122          if (isInvoiceReport) {
   123              if (ReportUtils.isIndividualInvoiceRoom(chatReport)) {
   124                  buttonOptions.push({
   125                      text: translate('iou.settlePersonal', {formattedAmount}),
   126                      icon: Expensicons.User,
   127                      value: CONST.IOU.PAYMENT_TYPE.ELSEWHERE,
   128                      backButtonText: translate('iou.individual'),
   129                      subMenuItems: [
   130                          {
   131                              text: translate('iou.payElsewhere', {formattedAmount: ''}),
   132                              icon: Expensicons.Cash,
   133                              value: CONST.IOU.PAYMENT_TYPE.ELSEWHERE,
   134                              onSelected: () => onPress(CONST.IOU.PAYMENT_TYPE.ELSEWHERE),
   135                          },
   136                      ],
   137                  });
   138              }
   139
   140              buttonOptions.push({
   141                  text: translate('iou.settleBusiness', {formattedAmount}),
   142                  icon: Expensicons.Building,
   143                  value: CONST.IOU.PAYMENT_TYPE.ELSEWHERE,
   144                  backButtonText: translate('iou.business'),
   145                  subMenuItems: [
   146                      {
   147                          text: translate('iou.payElsewhere', {formattedAmount: ''}),
   148                          icon: Expensicons.Cash,
   149                          value: CONST.IOU.PAYMENT_TYPE.ELSEWHERE,
   150                          onSelected: () => onPress(CONST.IOU.PAYMENT_TYPE.ELSEWHERE, true),
   151                      },
   152                  ],
   153              });
   154          }
   155
   156          if (shouldShowApproveButton) {
   157              buttonOptions.push(approveButtonOption);
   158          }
   159
   160          // Put the preferred payment method to the front of the array, so it's shown as default. We assume their last payment method is their preferred.
   161          if (lastPaymentMethod) {
   162              return buttonOptions.sort((method) => (method.value === lastPaymentMethod ? -1 : 0));
   163          }
   164          return buttonOptions;
   165          // We don't want to reorder the options when the preferred payment method changes while the button is still visible except for component initialization when the last payment method is not initialized yet.
   166          // We need to be sure that onPress should be wrapped in an useCallback to prevent unnecessary updates.
   167          // eslint-disable-next-line react-compiler/react-compiler, react-hooks/exhaustive-deps
   168      }, [
   169          isLoadingLastPaymentMethod,
   170          iouReport,
   171          translate,
   172          formattedAmount,
   173          shouldDisableApproveButton,
   174          isInvoiceReport,
   175          currency,
   176          shouldHidePaymentOptions,
   177          shouldShowApproveButton,
   178          shouldShowPaywithExpensifyOption,
   179          shouldShowPayElsewhereOption,
   180          chatReport,
   181          onPress,
   182          onlyShowPayElsewhere,
   183      ]);
   184
   185      const selectPaymentType = (event: KYCFlowEvent, iouPaymentType: PaymentMethodType, triggerKYCFlow: TriggerKYCFlow) => {
   186          if (policy && SubscriptionUtils.shouldRestrictUserBillableActions(policy.id)) {
   187              Navigation.navigate(ROUTES.RESTRICTED_ACTION.getRoute(policy.id));
