   189          }
   190
   191          if (iouPaymentType === CONST.IOU.PAYMENT_TYPE.EXPENSIFY || iouPaymentType === CONST.IOU.PAYMENT_TYPE.VBBA) {
   192              triggerKYCFlow(event, iouPaymentType);
   193              BankAccounts.setPersonalBankAccountContinueKYCOnSuccess(ROUTES.ENABLE_PAYMENTS);
   194              return;
   195          }
   196
   197          if (iouPaymentType === CONST.IOU.REPORT_ACTION_TYPE.APPROVE) {
   198              if (confirmApproval) {
   199                  confirmApproval();
   200              } else {
   201                  IOU.approveMoneyRequest(iouReport);
   202              }
   203              return;
   204          }
   205
   206          playSound(SOUNDS.SUCCESS);
   207          onPress(iouPaymentType);
   208      };
   209
   210      const savePreferredPaymentMethod = (id: string, value: PaymentMethodType) => {
   211          IOU.savePreferredPaymentMethod(id, value);
   212      };
   213
   214      return (
   215          <KYCWall
   216              onSuccessfulKYC={(paymentType) => onPress(paymentType)}
   217              enablePaymentsRoute={enablePaymentsRoute}
   218              addBankAccountRoute={addBankAccountRoute}
   219              addDebitCardRoute={addDebitCardRoute}
   220              isDisabled={isOffline}
   221              source={CONST.KYC_WALL_SOURCE.REPORT}
   222              chatReportID={chatReportID}
   223              iouReport={iouReport}
   224              anchorAlignment={kycWallAnchorAlignment}
   225              shouldShowPersonalBankAccountOption={shouldShowPersonalBankAccountOption}
   226          >
   227              {(triggerKYCFlow, buttonRef) => (
   228                  <ButtonWithDropdownMenu<PaymentType>
   229                      success
   230                      onOptionsMenuShow={onPaymentOptionsShow}
   231                      onOptionsMenuHide={onPaymentOptionsHide}
   232                      buttonRef={buttonRef}
   233                      shouldAlwaysShowDropdownMenu={isInvoiceReport}
   234                      customText={isInvoiceReport ? translate('iou.settlePayment', {formattedAmount}) : undefined}
   235                      menuHeaderText={isInvoiceReport ? translate('workspace.invoices.paymentMethods.chooseInvoiceMethod') : undefined}
   236                      isSplitButton={!isInvoiceReport}
   237                      isDisabled={isDisabled}
   238                      isLoading={isLoading}
   239                      onPress={(event, iouPaymentType) => selectPaymentType(event, iouPaymentType, triggerKYCFlow)}
   240                      pressOnEnter={pressOnEnter}
   241                      options={paymentButtonOptions}
   242                      onOptionSelected={(option) => {
   243                          if (policyID === '-1') {
   244                              return;
   245                          }
   246                          savePreferredPaymentMethod(policyID, option.value);
   247                      }}
   248                      style={style}
   249                      wrapperStyle={wrapperStyle}
   250                      disabledStyle={disabledStyle}
   251                      buttonSize={buttonSize}
   252                      anchorAlignment={paymentMethodDropdownAnchorAlignment}
   253                      enterKeyEventListenerPriority={enterKeyEventListenerPriority}
   254                      useKeyboardShortcuts={useKeyboardShortcuts}
   255                  />
   256              )}
   257          </KYCWall>
   258      );
   259  }
   260
   261  SettlementButton.displayName = 'SettlementButton';
   262
   263  export default SettlementButton;

