    22
    23  // This sets the Horizontal anchor position offset for POPOVER MENU.
    24  const POPOVER_MENU_ANCHOR_POSITION_HORIZONTAL_OFFSET = 20;
    25
    26  // This component allows us to block various actions by forcing the user to first add a default payment method and successfully make it through our Know Your Customer flow
    27  // before continuing to take whatever action they originally intended to take. It requires a button as a child and a native event so we can get the coordinates and use it
    28  // to render the AddPaymentMethodMenu in the correct location.
    29  function KYCWall({
    30      addBankAccountRoute,
    31      addDebitCardRoute,
    32      anchorAlignment = {
    33          horizontal: CONST.MODAL.ANCHOR_ORIGIN_HORIZONTAL.LEFT,
    34          vertical: CONST.MODAL.ANCHOR_ORIGIN_VERTICAL.BOTTOM,
    35      },
    36      chatReportID = '',
    37      children,
    38      enablePaymentsRoute,
    39      iouReport,
    40      onSelectPaymentMethod = () => {},
    41      onSuccessfulKYC,
    42      shouldIncludeDebitCard = true,
    43      shouldListenForResize = false,
    44      source,
    45      shouldShowPersonalBankAccountOption = false,
    46  }: KYCWallProps) {
    47      const [userWallet] = useOnyx(ONYXKEYS.USER_WALLET);
    48      const [walletTerms] = useOnyx(ONYXKEYS.WALLET_TERMS);
    49      const [fundList] = useOnyx(ONYXKEYS.FUND_LIST);
    50      const [bankAccountList = {}] = useOnyx(ONYXKEYS.BANK_ACCOUNT_LIST);
    51      const [reimbursementAccount] = useOnyx(ONYXKEYS.REIMBURSEMENT_ACCOUNT);
    52
    53      const anchorRef = useRef<HTMLDivElement | View>(null);
    54      const transferBalanceButtonRef = useRef<HTMLDivElement | View | null>(null);
    55
    56      const [shouldShowAddPaymentMenu, setShouldShowAddPaymentMenu] = useState(false);
    57
    58      const [anchorPosition, setAnchorPosition] = useState({
    59          anchorPositionVertical: 0,
    60          anchorPositionHorizontal: 0,
    61      });
    62
    63      const getAnchorPosition = useCallback(
    64          (domRect: DomRect): AnchorPosition => {
    65              if (anchorAlignment.vertical === CONST.MODAL.ANCHOR_ORIGIN_VERTICAL.TOP) {
    66                  return {
    67                      anchorPositionVertical: domRect.top + domRect.height + CONST.MODAL.POPOVER_MENU_PADDING,
    68                      anchorPositionHorizontal: domRect.left + POPOVER_MENU_ANCHOR_POSITION_HORIZONTAL_OFFSET,
    69                  };
    70              }
    71
    72              return {
    73                  anchorPositionVertical: domRect.top - CONST.MODAL.POPOVER_MENU_PADDING,
    74                  anchorPositionHorizontal: domRect.left,
    75              };
    76          },
    77          [anchorAlignment.vertical],
    78      );
    79
    80      /**
    81       * Set position of the transfer payment menu
    82       */
    83      const setPositionAddPaymentMenu = ({anchorPositionVertical, anchorPositionHorizontal}: AnchorPosition) => {
    84          setAnchorPosition({
    85              anchorPositionVertical,
    86              anchorPositionHorizontal,
    87          });
    88      };
    89
    90      const setMenuPosition = useCallback(() => {
    91          if (!transferBalanceButtonRef.current) {
    92              return;
    93          }
    94
    95          const buttonPosition = getClickedTargetLocation(transferBalanceButtonRef.current as HTMLDivElement);
    96          const position = getAnchorPosition(buttonPosition);
    97
    98          setPositionAddPaymentMenu(position);
    99      }, [getAnchorPosition]);
   100
   101      const selectPaymentMethod = useCallback(
   102          (paymentMethod: PaymentMethod) => {
   103              onSelectPaymentMethod(paymentMethod);
   104
   105              if (paymentMethod === CONST.PAYMENT_METHODS.PERSONAL_BANK_ACCOUNT) {
   106                  BankAccounts.openPersonalBankAccountSetupView();
   107              } else if (paymentMethod === CONST.PAYMENT_METHODS.DEBIT_CARD) {
   108                  Navigation.navigate(addDebitCardRoute);
   109              } else if (paymentMethod === CONST.PAYMENT_METHODS.BUSINESS_BANK_ACCOUNT) {
   110                  if (iouReport && ReportUtils.isIOUReport(iouReport)) {
   111                      const {policyID, workspaceChatReportID, reportPreviewReportActionID} = Policy.createWorkspaceFromIOUPayment(iouReport) ?? {};
   112                      if (workspaceChatReportID) {
   113                          Navigation.navigate(ROUTES.REPORT_WITH_ID.getRoute(workspaceChatReportID, reportPreviewReportActionID));
   114                      }
   115
   116                      // Navigate to the bank account set up flow for this specific policy
   117                      Navigation.navigate(ROUTES.BANK_ACCOUNT_WITH_STEP_TO_OPEN.getRoute('', policyID));
   118
   119                      return;
   120                  }
   121                  Navigation.navigate(addBankAccountRoute);
   122              }
   123          },
   124          [addBankAccountRoute, addDebitCardRoute, iouReport, onSelectPaymentMethod],
   125      );
   126
   127      /**
   128       * Take the position of the button that calls this method and show the Add Payment method menu when the user has no valid payment method.
   129       * If they do have a valid payment method they are navigated to the "enable payments" route to complete KYC checks.
   130       * If they are already KYC'd we will continue whatever action is gated behind the KYC wall.
   131       *
   132       */
   133      const continueAction = useCallback(
   134          (event?: GestureResponderEvent | KeyboardEvent, iouPaymentType?: PaymentMethodType) => {
   135              const currentSource = walletTerms?.source ?? source;
   136
   137              /**
   138               * Set the source, so we can tailor the process according to how we got here.
   139               * We do not want to set this on mount, as the source can change upon completing the flow, e.g. when upgrading the wallet to Gold.
   140               */
   141              Wallet.setKYCWallSource(source, chatReportID);
   142
   143              if (shouldShowAddPaymentMenu) {
   144                  setShouldShowAddPaymentMenu(false);
   145                  return;
   146              }
   147
   148              // Use event target as fallback if anchorRef is null for safety
   149              const targetElement = anchorRef.current ?? (event?.currentTarget as HTMLDivElement);
   150
   151              transferBalanceButtonRef.current = targetElement;
   152
   153              const isExpenseReport = ReportUtils.isExpenseReport(iouReport);
   154              const paymentCardList = fundList ?? {};
   155
   156              // Check to see if user has a valid payment method on file and display the add payment popover if they don't
   157              if (
   158                  (isExpenseReport && reimbursementAccount?.achData?.state !== CONST.BANK_ACCOUNT.STATE.OPEN) ||
   159                  (!isExpenseReport && bankAccountList !== null && !PaymentUtils.hasExpensifyPaymentMethod(paymentCardList, bankAccountList, shouldIncludeDebitCard))
   160              ) {
   161                  Log.info('[KYC Wallet] User does not have valid payment method');
   162
   163                  if (!shouldIncludeDebitCard) {
   164                      selectPaymentMethod(CONST.PAYMENT_METHODS.PERSONAL_BANK_ACCOUNT);
   165                      return;
   166                  }
   167
   168                  const clickedElementLocation = getClickedTargetLocation(targetElement as HTMLDivElement);
   169                  const position = getAnchorPosition(clickedElementLocation);
   170
   171                  setPositionAddPaymentMenu(position);
   172                  setShouldShowAddPaymentMenu(true);
   173
   174                  return;
   175              }
   176              if (!isExpenseReport) {
   177                  // Ask the user to upgrade to a gold wallet as this means they have not yet gone through our Know Your Customer (KYC) checks
   178                  const hasActivatedWallet = userWallet?.tierName && [CONST.WALLET.TIER_NAME.GOLD, CONST.WALLET.TIER_NAME.PLATINUM].some((name) => name === userWallet.tierName);
   179
   180                  if (!hasActivatedWallet) {
   181                      Log.info('[KYC Wallet] User does not have active wallet');
   182
   183                      Navigation.navigate(enablePaymentsRoute);
   184
   185                      return;
   186                  }
   187              }
   188
   189              Log.info('[KYC Wallet] User has valid payment method and passed KYC checks or did not need them');
   190
   191              onSuccessfulKYC(iouPaymentType, currentSource);
   192          },
   193          [
   194              bankAccountList,
   195              chatReportID,
   196              enablePaymentsRoute,
   197              fundList,
   198              getAnchorPosition,
   199              iouReport,
   200              onSuccessfulKYC,
   201              reimbursementAccount?.achData?.state,
   202              selectPaymentMethod,
   203              shouldIncludeDebitCard,
   204              shouldShowAddPaymentMenu,
   205              source,
   206              userWallet?.tierName,
   207              walletTerms?.source,
   208          ],
   209      );
   210
   211      useEffect(() => {
   212          let dimensionsSubscription: EmitterSubscription | null = null;
   213
   214          PaymentMethods.kycWallRef.current = {continueAction};
   215
   216          if (shouldListenForResize) {
   217              dimensionsSubscription = Dimensions.addEventListener('change', setMenuPosition);
   218          }
   219
   220          return () => {
   221              if (shouldListenForResize && dimensionsSubscription) {
   222                  dimensionsSubscription.remove();
   223              }
   224
   225              PaymentMethods.kycWallRef.current = null;
   226          };
   227      }, [chatReportID, setMenuPosition, shouldListenForResize, continueAction]);
   228
   229      return (
   230          <>
   231              <AddPaymentMethodMenu
   232                  isVisible={shouldShowAddPaymentMenu}
